<?php
declare(strict_types=1);require_once __DIR__.'/bootstrap.php';admin_require_login();$statuses=['pending','confirmed','processing','shipped','completed','cancelled'];$payStatuses=['unpaid','pending','paid','failed','refunded'];if($_SERVER['REQUEST_METHOD']==='POST'){admin_csrf_check();$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'');$payment=(string)($_POST['payment_status']??'');if(in_array($status,$statuses,true)&&in_array($payment,$payStatuses,true)){$s=$pdo->prepare('UPDATE orders SET status=?,payment_status=? WHERE id=?');$s->execute([$status,$payment,$id]);$_SESSION['flash']='Order status updated.';}else{$_SESSION['flash']='Invalid order status.';}redirect('orders.php'.($id?'?view='.$id:''));}
$view=(int)($_GET['view']??0);$detail=null;$items=[];if($view){$s=$pdo->prepare('SELECT * FROM orders WHERE id=?');$s->execute([$view]);$detail=$s->fetch();if($detail){$s=$pdo->prepare('SELECT * FROM order_items WHERE order_id=? ORDER BY id');$s->execute([$view]);$items=$s->fetchAll();}}
$q=trim((string)($_GET['q']??''));$filter=(string)($_GET['status']??'');$sql='SELECT * FROM orders WHERE 1=1';$params=[];if($q!==''){$sql.=' AND (order_number LIKE ? OR customer_name LIKE ? OR customer_phone LIKE ?)';$l='%'.$q.'%';$params=[$l,$l,$l];}if(in_array($filter,$statuses,true)){$sql.=' AND status=?';$params[]=$filter;}$sql.=' ORDER BY placed_at DESC LIMIT 250';$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();admin_page_start('Orders');if($view&&!$detail):?><div class="alert alert-warning">Order not found.</div><?php elseif($detail):?><div class="panel mb-4"><div class="d-flex flex-wrap justify-content-between align-items-start gap-2"><div><h2 class="h5 mb-1">Order <?=e($detail['order_number'])?></h2><div class="text-secondary small">Placed <?=e($detail['placed_at'])?> · Channel: <?=e($detail['order_channel'])?></div></div><a class="btn btn-outline-secondary btn-sm" href="orders.php">Back to orders</a></div><hr><div class="row g-3"><div class="col-md-6"><h3 class="h6">Customer and delivery</h3><p class="mb-1"><strong><?=e($detail['customer_name'])?></strong></p><p class="mb-1"><?=e($detail['customer_email']??'')?></p><p class="mb-1"><?=e($detail['customer_phone'])?></p><p class="mb-1"><?=e($detail['delivery_address'])?>, <?=e($detail['town'])?>, <?=e($detail['county'])?></p><p class="small text-secondary"><?=e($detail['delivery_notes']??'')?></p></div><div class="col-md-6"><h3 class="h6">Totals</h3><div>Subtotal: <?=e(money($detail['subtotal']))?></div><div>Delivery: <?=e(money($detail['delivery_fee']))?></div><div>Discount: <?=e(money($detail['discount_amount']))?></div><div class="fw-bold fs-5">Total: <?=e(money($detail['total_amount']))?></div><div class="mt-2">Method: <?=e($detail['payment_method'])?></div></div></div><hr><h3 class="h6">Items</h3><div class="table-responsive"><table class="table"><thead><tr><th>Product</th><th>SKU</th><th>Qty</th><th>Unit price</th><th>Line total</th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><?=e($it['product_name'])?></td><td><?=e($it['sku']??'—')?></td><td><?=(int)$it['quantity']?></td><td><?=e(money($it['unit_price']))?></td><td><?=e(money($it['line_total']))?></td></tr><?php endforeach;?></tbody></table></div><form method="post" class="row g-2 align-items-end"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$detail['id']?>"><div class="col-md-4"><label class="form-label">Order status</label><select class="form-select" name="status"><?php foreach($statuses as $v):?><option value="<?=$v?>" <?=$detail['status']===$v?'selected':''?>><?=ucfirst($v)?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Payment status</label><select class="form-select" name="payment_status"><?php foreach($payStatuses as $v):?><option value="<?=$v?>" <?=$detail['payment_status']===$v?'selected':''?>><?=ucfirst($v)?></option><?php endforeach;?></select></div><div class="col-md-4"><button class="btn btn-primary">Update order</button></div></form><p class="small text-warning mt-3 mb-0">Changing payment status here is a manual admin action; it does not verify an M-Pesa transaction or update payment gateway records.</p></div><?php endif;?><div class="panel"><form class="d-flex flex-wrap gap-2 mb-3"><input class="form-control" style="max-width:300px" name="q" placeholder="Search order, customer or phone" value="<?=e($q)?>"><select class="form-select" name="status" style="max-width:200px"><option value="">All statuses</option><?php foreach($statuses as $v):?><option value="<?=$v?>" <?=$filter===$v?'selected':''?>><?=ucfirst($v)?></option><?php endforeach;?></select><button class="btn btn-outline-secondary">Filter</button></form><div class="table-responsive"><table class="table"><thead><tr><th>Order</th><th>Customer</th><th>Date</th><th>Total</th><th>Status</th><th>Payment</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="text-center text-secondary">No orders found.</td></tr><?php else:foreach($rows as $r):?><tr><td class="fw-semibold"><?=e($r['order_number'])?></td><td><?=e($r['customer_name'])?><div class="small text-secondary"><?=e($r['customer_phone'])?></div></td><td><?=e($r['placed_at'])?></td><td><?=e(money($r['total_amount']))?></td><td><?=e(ucfirst($r['status']))?></td><td><?=e(ucfirst($r['payment_status']))?></td><td><a class="btn btn-sm btn-outline-primary" href="orders.php?view=<?=(int)$r['id']?>">View / update</a></td></tr><?php endforeach;endif;?></tbody></table></div></div><?php admin_page_end();?>
